Assume that $M>C_\tau\sqrt{D\log D}$.  Denote $\mathbf{p} = Proj_{\mathcal{M}} (r)$ where r is the input point for Algorithm alg:step2_clean.
	Let $(q, H)$ be an initial coordinate system for which $\left\Vert q - p \right\Vert\leq 3 \sigma$ and $ \angle_{\max} (H, T_p\mathcal{M}) \leq \sqrt{c_{M}/M}$, where $p= Proj_{\mathcal{M}}(q) \in \mathcal{M}$.
	For any $\delta>0$ arbitrarily small, denote by $ \hat p_n, \widehat{T_{\hat p_n}\mathcal{M}} $ the estimates derived from Algorithm alg:step2_clean initialized with $(q,H)$ with the number of iterations $\kappa$ specified in Lemma 10.4. Then, there is $ N_{\delta} $ such that for all $ n > N_{\delta}  $ we have 
	\begin{equation}
		dist(\hat p_n, \mathcal{M}) \leq \frac{C_1\ln\left(\frac{1}{\delta}\right)}{n^{r_0}}= \mathcal{O}(n^{-r_0}),
	\end{equation}
	\begin{equation}
		\left\Vert \hat p_n - \mathbf{p} \right\Vert \leq C_2\ln\left(\frac{1}{\delta}\right) \left(\frac{ n}{\ln\left(\ln(n) \right)^2}\right)^{-r_1} = \widetilde{\mathcal{O}}(n^{-r_1})  ,
	\end{equation}
	and 
	\begin{equation}
		\angle_{\max}(\widehat{T_{\hat p_n}\mathcal{M}},T_{\mathbf p}\mathcal{M}) \leq C_3\ln\left(\frac{1}{\delta}\right) \left(\frac{ n}{\ln\left(\ln(n) \right)^2}\right)^{-r_1} = \widetilde{\mathcal{O}}(n^{-r_1})    
	\end{equation}
	with probability of at least $ 1 - \delta $, where $ r_0 = \frac{k}{2k +d}, r_1 = \frac{k-1}{2k +d} $, and $ C_1,C_2,C_3$ are constants independent of $d, \delta$.

Let the conditions of Lemma 10.10 hold.
Let $g(x, \theta), \widetilde{x}(x)$ be as defined in Equation (87) and (88) respectively, let $I_d:\mathbb{R}^d\to\mathbb{R}^d$ denote the identity matrix and let $J_{\widetilde{x}_\theta}$ denote the differential of $\widetilde{x}(x)$ with respect to $x$. Then, 
\begin{equation*}
\|I_d-J_{\widetilde{x}_\theta}[0]\| = \mathcal{O}(\frac{\sigma}{\tau})
.\end{equation*}

Let the conditions of Lemma 10.11 hold, let $w(x, \widetilde{x}_\theta)$ be as defined in (105), $\widetilde{x}_\theta(x)$ be as defined in (88), and $\Delta$ as defined in (100). 
Denote by $\mathcal{D}^x_w, \mathcal{D}^{\widetilde{x}_\theta}_w$ the partial differentials of $w$ with respect to the variables $x$ and $\widetilde{x}_\theta$.
Then, for $\alpha$ smaller than some constant
\begin{equation}
    \frac{1}{2} \sigma^2 \leq \Delta(0,\widetilde{x}_\theta (0)) \leq 2 \sigma^2
,\end{equation}
\begin{equation} 
\| \mathcal{D}^{\widetilde{x}_\theta}_ w[0, \widetilde{x}_\theta(0)] \| \leq  \mathcal{O}(\sin \alpha) \qquad \|\mathcal{D}^x_w[0, \widetilde{x}_\theta(0)]\| \leq \mathcal{O}(\sin \alpha)
,\end{equation}
and
\begin{equation}
\| \mathcal{D}^{\widetilde{x}_\theta}_w[0, \widetilde{x}_\theta(0)] + \mathcal{D}^x_w[0, \widetilde{x}_\theta(0)]\| \leq \mathcal{O}(\frac{\sigma}{\tau}\sin \alpha)
.\end{equation}

3Let the conditions of Lemma 10.6 hold. Let $\widetilde{x}_\theta(x)$ be as defined in equation (88) in the proof of Lemma 10.6.
Then, for any unit vector $\theta\in \mathbb{R}^{D-d}$, if $\alpha, \frac{\sigma}{\tau}$ are smaller than some constants, we have
	\begin{equation*}
	\|\widetilde{x}_\theta(0)\| \leq \sigma \sin (\alpha + c\frac{\sigma}{\tau}\alpha)
	\end{equation*}
 for some general constant $c\in\mathbb{R}$.
